INSERT INTO app_private.actors (
    id, slug, name, description, category_id, type_id, region_id, address,
    city, state_code, phone, email, website, instagram, location,
    verification_status, created_at, updated_at
) VALUES (
    '4c4ae32b-f56d-5b33-befc-b2208010e2bb', 'orla-do-cais-de-altamira-atm_0486', 'Orla do Cais de Altamira', 'A Orla do Cais de Altamira é um local encantador às margens do Rio Xingu, ideal para lazer e contemplação da natureza amazônica. É um ponto que reúne paisagem e gastronomia. As atividades incluem passeios, fotografia e contemplação do pôr do sol. O público-alvo é composto por famílias, casais e jovens. Recomenda-se atenção ao aluguel de chalanas para eventos. As coordenadas e o endereço são baseados em fontes de mapeamento e vídeos, com a categoria principal sendo ''Nossa Cidade'' (visitaltamira:6:320ea3a512|categoria_principal).',
