) VALUES (
    'be2ded49-b5f4-5b3d-9306-97e251df1eaf', 'orla-do-trapiche-atm_0765', 'Orla do Trapiche', 'A Orla do Trapiche em Altamira/PA é um local de lazer com foco em ecoturismo, pesca e observação da natureza. Possui estrutura como orla, rio Xingu e é acessível para cadeirantes. O endereço mais completo é fornecido pelo Google Maps (R. Cel. José Porfírio, 2321 - Esplanada do Xingu). As fontes indicam atividades como pesca esportiva e passeios de canoa/caiaque.',
    (SELECT id FROM app_private.actor_categories WHERE slug = 'experiencias'),
    (SELECT id FROM app_private.actor_types WHERE slug = 'nao_classificado'),
    'a17a314a-0000-4000-8000-000000000001', 'Orla de Altamira, Pará', 'Altamira', 'PA',
    NULL, NULL, NULL, NULL,
    extensions.ST_SetSRID(extensions.ST_MakePoint(-52.2093272, -3.2101465), 4326)::extensions.geography, 'unverified',
